INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (1, 'Jun', 'El Todo, La Unidad, El Absoluto, La Pureza', 'Principio de Unidad.<br><span></span>Propósito, Atraer, Unificar.<br><span></span>El principio y origen, el ser humano como un todo.<br><span></span>La unidad establece el propósito, el objeto y la meta de acción por pequeña que esta sea.<br><span></span>La unidad es el todo, la única verdad absoluta, es la creación mental del todo.<br><span></span>En el circulo de la perfección todos los seres están unidos inseparablemente sin importar su dimensión de manifestación, la creencia de que no es así, crea una grieta en la relación original y esa grieta en el campo de energía crea una polaridad (como proceso de cicatrización) que ha de convertirse en vibración.', 'Jun', 'Energia_1', '<br><span>Ati\'taj re ojer sk\'ulal.</span>
<br><span>Jun rech ulew, rik\'ulal, chik\'ulal.</span>
<br><span>Ati\'taj rech ulew, ati\'taj k\'aslemal, jun ajk\'ojol rech ulew.</span>
<br><span>Ojer sk\'ulal ri k\'aslemal, ri ak\'aslemal, re jolom wach ulew k\'aj k\'uwi\'.</span>
<br><span>Ati\'taj rech ulew, jun ulew, jun ronoqilal ajk\'ojol, ati\'taj chik\'ulal, re jolom wach ulew.</span>
<br><span>Ati\'taj rech ruwi\' ri lal, ri chi\', re aq\'ab\'al k\'aslemal, ati\'taj, ki\'k\'ak\' ri aq\'ab\'al e k\'aslemal, ki\'k\'ak\' k\'aslemal e k\'ojojilal chi ri chik\'ulal e k\'uwi\' (ti\'a\'j).</span>
', '<p>Principio tu Junp’éel.</p>
<p>Taj, Ts’a’, Juntúul.</p>
<p>Le juntúul ku ts’áik u tuukul, u máanil yéetel u kúuch.</p>
<p>Junp’éel tuukul le’ ku meyaj juntéene’, mixba’ate’ex bey ts’áama’.</p>
<p>Junp’éel ku chi’in, le ba’ax ja’atsik yéetel ku nukuchpajal.</p>
<p>Tu ja’atsik le ba’alo’ob tu k’áajóolil, ichil le k’áaxo’ ku chan iknal u tsol óoltajo’ob, k’a’ajtal le meyajil u vibración.</p>', '<p>Principle of Unity.</p>
<p>Purpose, Attract, Unify.</p>
<p>The principle and origin, the human being as a whole.</p>
<p>Unity establishes purpose, object, and goal of action no matter how small it may be.</p>
<p>Unity is the whole, the only absolute truth, it is the mental creation of the whole.</p>
<p>In the circle of perfection, all beings are inseparably united regardless of their dimension of manifestation. The belief that it is not so creates a crack in the original relationship, and that crack in the energy field creates a polarity (as a healing process) that must become vibration.</p>
', '<p>
    Ri\' xk\'utij ch\'uti\'al kiwi. <br>
    <span></span> <br>
    Tz\'ikin ri\' ch\'uti\'al, chi\' aj, chi\' atak\'ij. <br>
    <span></span> <br>
    Ri\' xk\'utij k\'o\', ri\' ulew, wi\' ruma wi\' winaq chi ri\' k\'o\' xk\'utij. <br>
    <span></span> <br>
    Ri\' xk\'utij tujuj ruma\'aj, ri\' tijonelaj wi\' ruma ri\' tijonelaj k\'i\' ruch\'aj. <br>
    <span></span> <br>
    Ri\' xk\'utij ch\'uti\'al xk\'utij, ri\' xk\'utij ruk\'ub\'al ri\' ulew, wi\' xk\'utij k\'o\' k\'i\' ri\' tijonelaj chi\' xchi\', chwi\' uq\'ij ruma k\'i\' rachin ri\' k\'o\' k\'o\' xk\'utij. <br>
    <span></span> <br>
    K\'o\' ri\' xelajk\'arab\', k\'o\' winaq wi\' winaq xk\'utij xub\'anik xk\'utij tijonelaj, chwi\' ruma k\'o\' wi\' k\'o\' xk\'utij, ruch\'aj ch\'uti\'al xk\'utij (xi\' kaj xk\'utij k\'u\'xaj k\'o\' wi\' <em>xi\'aj q\'ochuq\'a</em>) xchi\' k\'u\'xaj k\'i\' ruk\'ub\'al (xi\' k\'u\'xaj ch\'uti\'al wi\' wi\' tijonelaj) xk\'utij xub\'anik. 
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (2, 'Keb\'', 'La Pareja, La Polaridad, El Complemento, El Apoyo', 'Principio de Polaridad.<br><span></span>Desafió, Estabilizar, Polarizar.<br><span></span>Esqueleto y esencia, Masculino y femenino; forman el principio generador dual, la simetría dual de los seres. Son los extremos de un mismo fenómeno, opuestos idénticos en su naturaleza: espíritu y materia, luz y oscuridad, yin y yang.<br><span></span>Armonizar la vibración es resolver la polaridad equilibrando los dos extremos, o sea, incluyéndolos<br><span></span>Si todo es luz, las formas se difuminan, por eso es necesario el contraste de las sombras.<br><span></span>Cultivar nuestra resonancia es armonizar nuestra vibración con resonancias superiores como la planetaria, solar y galáctica.', 'Ka\'a', 'Energia_2', '<span>Principio de Polaridad.</span>
<br><span>K\'ak\'alaj, Tzijolaj, K\'ak\'alikaj.</span>
<br><span>Chik\' ri k\'utin e winaq, xk\'utin re q\'ak\'altun chik\' ri k\'utin k\'ojojilal, uk\'ux ri k\'utin k\'ojojilal re winaq. Re winaq ri q\'ak\'altun ri ri k\'ojojilal, k\'utin ajk\'ojol rech uk\'ux e k\'ojojilal, chiri\' ajk\'ojolaj chiri\' re k\'utin e re winaq: ri leb\', ri xan, ri t\'ijon, ri t\'zel, ri ulew, ri k\'ajol.</span>
<br><span>K\'ak\'alikaj ri k\'aslemal xk\'utin winaq tijob\'al ri k\'ak\'alaj k\'utin, k\'u\'x ri uk\'ux ri k\'ojojilal e re winaq, o sea, tijob\'alaj e re winaq</span>
<br><span>Man chi re leb\', re ch\'olaj xk\'utin winaq, ri ta chik\' chwachik, chik\' xk\'utin xk\'utin re q\'ak\'altun winaq.</span>
<br><span>Tzijolaj ri\' xk\'utin winaq tijob\'al ri q\'ak\'altun re chik\' k\'ak\'ul ri k\'ak\'ul, k\'u\'x ri q\'ak\'altun tijob\'al planetario, solar y galáctico.</span>
', '<p>Principio tu K’áak’ K’áak’al.</p>
<p>Ret’o’, K’áak’, Paach.</p>
<p>Tu’uxilil ts’u’uts’ yéetel meyaj; máak yéetel ixik, ka’at chi’oba’.</p>
<p>Ka’anik u tsotso’obo’ le k’áak’al, k’áat u ts’aik bin xíimbal.</p>
<p>Wa le k’áak’al ma’ tu ts’íib, mix uts’ jump’éel junp’éel.</p>
<p>Tóok u k’áaxo’ u tsol tu vibración ku chan bin kexik ti’ kaab, K’iin, ka jo’otik k’iinil Kaab’náal.</p>', '<p>Principle of Polarity.</p>
<p>Challenge, Stabilize, Polarize.</p>
<p>Skeleton and essence, Masculine and feminine; they form the dual generative principle, the dual symmetry of beings. They are the extremes of the same phenomenon, identical opposites in their nature: spirit and matter, light and darkness, yin and yang.</p>
<p>Harmonizing vibration is resolving polarity by balancing the two extremes, that is, including them.</p>
<p>If everything is light, forms blur, which is why the contrast of shadows is necessary.</p>
<p>Cultivating our resonance is harmonizing our vibration with higher resonances such as planetary, solar, and galactic ones.</p>
', '<p>
    Ri\' xk\'utij k\'u\'xaj k\'o\' k\'o\' ri\' k\'ak\'al. <br>
    <span></span> <br>
    Tz\'ikin, Chijolaj, K\'u\'xaj. <br>
    <span></span> <br>
    Ri\' xk\'utij kaj k\'o\', ri\' maya, wi\' xk\'utij wi\' winik; ruch\'aj k\'u\'xaj ruk\'ub\'al k\'o\', ri\' wuj ch\'utij k\'u\'xaj kaj, ruch\'aj chak\'ik ruch\'aj ruk\'ub\'al wi\' winaq. Ri\' tijonelaj k\'u\'xaj xk\'utij k\'i\' chak\'ik k\'i\' xk\'utij wi\' wi\', ruma ruma\'aj xk\'utij k\'i\' k\'u\'xaj: ri\' riwajil ch\'uti\'al ri\' juyub\' k\'i\' k\'o\' ri\' k\'ak\'al, ri\' k\'otz\'ij k\'i\' chi\', k\'u\'xaj k\'i\' xk\'utij; ch\'uti\'al k\'u\'xaj k\'i\' yin k\'i\' yang. <br>
    <span></span> <br>
    Ch\'uti\'al ri\' winaq k\'u\'xaj k\'o\' chwi\' xk\'utij k\'i\' riwajil k\'u\'xaj k\'u\'xaj, k\'o\' xk\'utij, ch\'uti\'al k\'u\'xaj xub\'anik. <br>
    <span></span> <br>
    Mew ri\' juyub\' k\'i\' witz, ri\' tinamit chik, chwi\' chik\', k\'u\'xaj ruma\'aj k\'i\' xchi\' chak\'ik k\'i\' xk\'utij chik\'. <br>
    <span></span> <br>
    Tinamit k\'o\' k\'u\'xaj k\'i\' k\'u\'xaj, ri\' tinamit chi\' xch\'utij xub\'anik k\'u\'xaj chi\' xub\'anik, chwi\' ch\'uti\'al xk\'utij k\'i\' ch\'uti\'al k\'u\'xaj k\'i\' ri\' planeta, solar k\'i\' galáctica.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (3, 'Oxib\'', 'Los Resultados, Los Hijos, El Temor, Los Frutos', 'Principio del ritmo o compensación.<br><span></span>Servicio, Unir, Activar.<br><span></span>Flujo y reflujo, ascenso y descenso, acción y relación; es el movimiento entre los polos de todos los planos (físico, mental y espiritual).<br><span></span>Cada fenómeno, cada proceso tiene su propio ritmo: todo tiene un inicio, nace, crece, muere y renace. Liquido precioso que da calor y energía al cuerpo, sangre, el agua de la naturaleza, lluvia.<br><span></span>Al crear polaridades, desencadenamos eventos, circunstancias que experimentamos y superamos, las acciones que producen un campo de negatividad (ignorancia, oscuridad espiritual) son kharmas, las acciones que suprimen y corrigen la negatividad (sabiduría) son Dharmas y crean un campo benéfico.', 'Ox', 'Energia_3', '<span>Principio del ritmo o compensación.</span>
<br><span>Q\'inal, Xub\'an, Xtz\'aj.</span>
<br><span>Re ch\'ajaq e k\'ajk\'ab\'al, re jup\'aj e q\'ajolaj, re winaq e q\'ak\'altun; ati\'taj e ojer q\'ojol ri rech xk\'utin e re ulew (físico, mental y espiritual).</span>
<br><span>Jun ri k\'ajk\'ab\'al, jun ri q\'ajolaj ri rech uk\'ux k\'uwi\' ati\'taj k\'ajolaj: jun ri chikin, ri pek\', ri ch\'olaj, ri waq\', ri wachaj.</span>
<br><span>Ati\'taj rech q\'ak\'altun xk\'utin, ati\'taj xk\'utin q\'ak\'altun e k\'ak\'ul, re winaq rech ri k\'ajolaj e winaq xk\'utin (ajk\'olom, wachaj, t\'zel e k\'ojojilal) re ulew k\'ojojilal, re q\'u\'p\'o\', ri aq\'ab\'al q\'utin, re ulew q\'utin.</span>
', '<p>Principio tu Ritmo.</p>
<p>Meyaj, Mets’ juntéene’, K’úuch.</p>
<p>Múul yéetel ch’ooj, nojoch ka báalche’, noj k’ab yéetel pak’atal.</p>
<p>Túumben ba’ax ku si’ij jumpéel, ku xíimbal, ku kíim, ka ts’o’ok uts.</p>
<p>Jo’ ch’aik jun há, le koolajilil k’áat u lu’umo’, ja’, ja’áak’.</p>
<p>K’áak’al ku sut ba’axalo’ob: karmalo’ob ku ts’a’ik u xikinil, dharmalo’ob ku ts’a’ik u nach’ilil.</p>', '<p>Principle of Rhythm or Compensation.</p>
<p>Service, Unite, Activate.</p>
<p>Flow and ebb, ascent and descent, action and relation; it is the movement between the poles of all planes (physical, mental, and spiritual).</p>
<p>Every phenomenon, every process has its own rhythm: everything has a beginning, is born, grows, dies, and is reborn. Precious liquid that gives warmth and energy to the body, blood, the water of nature, rain.</p>
<p>By creating polarities, we trigger events, circumstances that we experience and overcome. The actions that produce a field of negativity (ignorance, spiritual darkness) are karmas; the actions that suppress and correct the negativity (wisdom) are Dharmas and create a beneficial field.</p>
', '<p>
    Ri\' xk\'utij ch\'uti\'al k\'u\'xaj k\'o\' <em>compensación</em>. <br>
    <span></span> <br>
    Tz\'ikin, Ch\'uti\'al, <em>activar</em>. <br>
    <span></span> <br>
    K\'u\'xaj chi\' k\'otz\'ij k\'i\' k\'u\'xaj, chi\' k\'oxo\'chik k\'i\' k\'u\'xaj, ch\'uti\'al k\'i\' chak\'ik k\'i\' ch\'uti\'al; ch\'uti\'al k\'i\' k\'u\'xaj xk\'utij k\'i\' ri\' k\'ak\'al (físico, mental k\'i\' espiritual). <br>
    <span></span> <br>
    Ruma\'aj juyub\' k\'i\' witz, ruma\'aj tinamit k\'i\' k\'u\'xaj k\'u\'xaj: tinamit k\'o\' k\'u\'xaj chak\'ik, k\'o\' k\'i\' riwajil, k\'o\' k\'oxo\'chik, k\'o\' k\'u\'xaj k\'i\' k\'o\' k\'i\' chik\', chik\' k\'u\'xaj k\'i\' riwajil, riwajil k\'u\'xaj. Lich puk\'uj xik\'al ch\'uti\'al chi riwajil k\'u\'xaj k\'i\' ri\' winaq, chik\', ri\' ruma\'aj riwajil tinamit, k\'i\' k\'u\'xaj k\'o\' chi\' ulew, chik\', chuchul xk\'utij. <br>
    <span></span> <br>
    Chwi\' xk\'utij k\'u\'xaj k\'o\' ch\'uti\'al k\'u\'xaj, ch\'uti\'al k\'i\' k\'u\'xaj xub\'anik k\'i\' xk\'utij k\'u\'xaj, ri\' ch\'uti\'al k\'i\' k\'ak\'al chak\'ik ch\'uti\'al k\'u\'xaj k\'o\' k\'o\' kharmas, ri\' ch\'uti\'al k\'i\' k\'ak\'al chak\'ik ch\'uti\'al k\'u\'xaj k\'i\' ch\'uti\'al k\'u\'xaj (sabiduría) k\'o\' Dharmas chik\', k\'o\' chwi\' ch\'uti\'al xk\'utij xk\'utij.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (4, 'Kajib\'', 'La Solidez, La Fortaleza, La Felicidad, La Estabilidad', 'Principio de la medida.<br><span></span>Forma, Medir, Definir.<br><span></span>El cuatro como medida de todas las estructuras materiales (la pirámide), entra siempre en relación con la composición trina de lo espiritual, formando la estructura Septernal de todo lo que Es.<br><span></span>El poder del ordenamiento matemático del macro y microcosmos. Todo cuanto existe es según la medida de la ley del todo.<br><span></span>Establece los limites de las estructuras; las 4 fuerzas principales, 4 rumbos sagrados, 4 elementos: calor, viento y agua sobre tierra. Cuatro son las regiones mayas, 4 los elementales, 4 los nucleótidos, 4 los elementos químicos primarios, 4 las razas cósmicas, rumbos cardinales, estaciones solares, chacras de personalidad, etc', 'Kan', 'Energia_4', '<span>Principio de la medida.</span>
<br><span>Ri xk\'utin, Ri ri b\'antaj, Ri q\'ut\'olaj.</span>
<br><span>Ri kal chik\'in e xk\'utin xk\'utin chiri\' rech ri q\'ak\'altun ulew (ri pirámide), ronoqilal chi\' rech ri winaq k\'ojojilal q\'utin e re winaq e q\'utin, k\'u\'x re ajk\'ojolaj ulew k\'aj k\'uwi\' rech ri Ajaw ulew q\'utin.</span>
<br><span>Rech ajk\'ojolaj e ri riwach\'owin q\'utin e winaq e ulew. Ati\'taj chiri\' re winaq k\'ojojilal re ri xk\'utin e ajk\'ojolaj ri k\'ojojilal.</span>
<br><span>Ati\'taj rech k\'utin ri re k\'ajk\'otaj e ri xk\'utin; ri k\'ojojilal rech k\'utin uk\'ux, ri b\'antaj rech ri k\'utin, ri chik\'in ch\'ajol ri b\'antaj: wi\', nawal e wachaj chiri\' ulew. Kal chik\'in re ulew maya, k\'ajk\'otaj re wi\', nawal re uch\'ab\'al, k\'ajk\'otaj re b\'antaj k\'utin, k\'ajk\'otaj re riwach\'owin k\'utin, k\'ajk\'otaj re b\'e ulew chik\'in, ri b\'antaj, ri riwach\'owin rech ri ajaw k\'utin, etc.</span>
', '<p>Principio tu Kuxtalil Tso’ots’.</p>
<p>Formaj, Meen, Taan.</p>
<p>Le káa’p’éel ku ts’a’ u táanil jump’éel ba’axil (piramide).</p>
<p>Táanil k’áach ku tsol máaxo’ yéetel nojoch kaajo’.</p>
<p>Ku t’aan u jats’kabilil nojoch k’áax, 4 k’áaxil, 4 tuukul, 4 elementales.</p>', '<p>Principle of Measurement.</p>
<p>Form, Measure, Define.</p>
<p>The four as a measure of all material structures (the pyramid), always enters into relationship with the triune composition of the spiritual, forming the Septenary structure of all that Is.</p>
<p>The power of the mathematical ordering of the macro and microcosmos. Everything that exists is according to the measure of the law of the whole.</p>
<p>It establishes the limits of structures; the 4 main forces, 4 sacred directions, 4 elements: heat, wind, and water over earth. There are four Mayan regions, 4 elementals, 4 nucleotides, 4 primary chemical elements, 4 cosmic races, cardinal directions, solar seasons, personality chakras, etc.</p>
', '<p>
    Ri\' xk\'utij k\'u\'xaj <em>medida</em>. <br>
    <span></span> <br>
    Ri\' riwajil, K\'u\'xaj, Juyub\'. <br>
    <span></span> <br>
    Ri\' k\'o\' riwajil riwajil k\'i\' ch\'uti\'al k\'u\'xaj (ri\' pirámide), chi\' ch\'uti\'al chi\' k\'i\' k\'u\'xaj riwajil, ruch\'aj k\'i\' ch\'uti\'al chij trino wi\' ri\' k\'ak\'al, xub\'anik riwajil xk\'utij Septernal k\'i\' riwajil ri\' winik. <br>
    <span></span> <br>
    Ri\' ch\'uti\'al k\'u\'xaj riwajil ri\' tinamit wi\' riwajil winaq. Ruma\'aj riwajil k\'u\'xaj k\'o\' ri\' juyub\' k\'i\' k\'ak\'al xk\'utij juyub\' ri\' riwajil ri\' tinamit. <br>
    <span></span> <br>
    Ri\' xk\'utij tujuj k\'o\' ch\'uti\'al; ri\' k\'o\' ch\'uti\'al chij chak\'ik, ri\' k\'o\' winaq k\'o\' k\'u\'xaj ruk\'ub\'al, ri\' k\'o\' tijonelaj: ruch\'aj, wi\' k\'i\' k\'a\', k\'i\' ri\' k\'u\', ch\'uti\'al chi\' ulew. Ruk\'ub\'al k\'u\'xaj ri\' tinamit maya, k\'o\' xk\'utij k\'u\'xaj, k\'o\' riwajil, k\'o\' k\'i\' nucleótidos, k\'o\' k\'i\' elementales k\'o\' k\'i\' elementales k\'u\'xaj, k\'o\' k\'i\' elementales químicos k\'i\' primarios, k\'o\' k\'i\' chik\' ruk\'ub\'al, rumbos cardinales, tinamit solar, chakras k\'i\' personalidad, etc.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (5, 'Job\'', 'El Amor, El Trabajo, El Esfuerzo, Analizar', 'Principio de lo nuclear.<br><span></span>Esplendor, Mandar, Dar poder.<br><span></span>La capacidad de realización, la movilidad de los dedos, percibir la belleza de la naturaleza, el 5to. punto o centro del Universo.<br><span></span>Toda unidad, por pequeña que sea, objetiva o subjetiva comporta un núcleo como atractor y una periferia de manifestación (núcleo del átomo y electrones, por ejemplo).<br><span></span>Deriva la concepción del matiz cromático de cinco, que es la acción de la quinta fuerza galáctica; el matiz del color da la entonación.', 'Jo', 'Energia_5', '<span>Principio de lo nuclear.</span>
<br><span>K\'aslemal, Tijob\'al, K\'a\'wachaj.</span>
<br><span>Ri ati\'taj e ri k\'ajk\'otaj, ri ajk\'otaj e ri wi\', ri ak\'utin ri k\'utin, re 5to. jun che e uk\'ux ulew.</span>
<br><span>Jun q\'ak\'altun, ri chik\'in ch\'ajol, chiri\' ri ch\'ajol chik\'in, ajk\'utin ri winaq e q\'utin (núcleo ri aq\'ab\'al e electrones, xk\'utin).</span>
<br><span>Ati\'taj ri ri\'aj k\'aslemal e q\'ij q\'ij e ri chik\'in k\'i\' ri wi\', jun uk\'ux k\'uwi\' rechajch\'aj chik\'in.</span>
', '<p>Principio tu Nucleo.</p>
<p>Luum, Mandaméento, Chóoch.</p>
<p>Táan u ya’alil u tsool, u óotsil k’ab, tuukulil le naturaleza.</p>
<p>Tu jump’éel atomo ku yáantal nuclejo’ yéetel electrono’obo’.</p>
<p>Le óotsil 5 ku t’aan u ts’u’uts’ sak-kaan k’iin; le tonalil ku máan u ts’íib.</p>', '<p>Principle of the Nuclear.</p>
<p>Splendor, Command, Empower.</p>
<p>The capacity for realization, the mobility of the fingers, perceiving the beauty of nature, the 5th point or center of the Universe.</p>
<p>Every unit, no matter how small, objective or subjective, has a nucleus as an attractor and a periphery of manifestation (the nucleus of the atom and electrons, for example).</p>
<p>The conception of the chromatic hue of five derives from it, which is the action of the fifth galactic force; the hue of color gives the intonation.</p>
', '<p>
    Ri\' xk\'utij wi\' riwajil k\'o\' <em>lo nuclear</em>. <br>
    <span></span> <br>
    Chuchul, Ri\' tijonelaj, Ta ach\'iy. <br>
    <span></span> <br>
    Ri\' tinamit k\'i\' tijonelaj, ri\' yajawal xk\'utij xk\'utij, k\'i\' k\'i\' tinamit k\'o\' riwajil, ri\' k\'it chikop k\'o\' k\'u\'xaj. <br>
    <span></span> <br>
    Ruch\'aj k\'i\' ch\'uti\'al, ruma\'aj ch\'uti\'al, ri\' tinamit xub\'anik, tinamit tijonelaj k\'i\' k\'o\' winaq, juyub\' ruch\'aj k\'o\' ruch\'aj, ri\' nukle\'oj k\'o\' chi\' tijonelaj k\'i\' xk\'utij (nukle\'ojoj k\'i\' k\'atomo k\'i\' elektronelaj, ruma\'aj chik\', ruma\'aj k\'i\' ch\'uti\'al). <br>
    <span></span> <br>
    Ri\' juyub\' k\'i\' tinamit k\'i\' winaq k\'i\' tinamit ulew, ruch\'aj k\'o\' k\'otz\'ij, chi\' xk\'utij k\'i\' k\'i\' yin ruk\'ub\'al k\'i\' galáctica; tinamit juyub\' k\'o\' tinamit k\'i\' chi\' tonalidades k\'i\' tinamit chik\', tonalidad tijonelaj k\'i\' ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (6, 'Waqib\'', 'El Mundo Material, La Materia, La Amistad, La Reacción', 'Principio del equilibrio orgánico: 2x3. (Polaridad por ritmo)<br><span></span>Igualdad, Equilibrar, Organizo.<br><span></span>La polaridad del ritmo genera el principio orgánico, la ley del ordenamiento Hexagonal de las estructuras cristalinas y celulares. La tendencia de las estructuras ligadas al proceso de la vida es la de alcanzar el equilibrio relativo, estado de realización intermedio, a partir del cual continuar el movimiento hacia la conciencia superior.<br><span></span>El principio del Diferencial de Potencial aporta la resolución de situaciones a través de saltos cualitativos entre estados de la energía. Nada de cuanto sucede es casual, todo esta sujeto al poder de la ley primigenia; todo efecto tiene su causa y a la vez es causal de otros efectos, la Causa Centro Primera es el Creador.<br><span></span>Su acción es equilibrar, el principio de la integración de nuestra introspección', 'Wak', 'Energia_6', '<span>Principio del equilibrio orgánico: 2x3. (Polaridad por ritmo)</span>
<br><span>Tijob\'alaj, Ri tijob\'alaj, Tijob\'alikaj.</span>
<br><span>Ri k\'aslemal rechajch\'aj tijob\'al k\'utin re ajk\'otaj ulew, ri q\'atij ri winaq k\'utin winaq ri ri ajk\'ojolaj Xexonal re ri q\'ak\'altun ri k\'utin cristalino y q\'utin ch\'ajol. Re winaq ri winaq k\'utin chi\' ri ajk\'ojolaj ri xk\'utin ri re ri winaq ri ati\'taj ri ri winaq ri ch\'ajol chik\'in, ulew ri k\'ajk\'otaj uk\'ux, ri ri winaq winaq uk\'ux, chiri\' re chik\'in ajk\'ojolaj k\'ojojilal k\'uwi\' ri tijob\'al, k\'u\'x ri k\'ojojilal ri k\'ajk\'otaj ati\'taj ri q\'ak\'altun winaq e k\'uwi\' k\'utin chiri\' re chik\'in winaq ri\' ri winaq k\'ojojilal k\'utin.</span>
<br><span>Ri q\'atij ri rechajch\'aj uk\'ux ri chik\'in ati\'taj ri rechajch\'aj q\'atij re ri q\'atij ri winaq. Man xk\'utin winaq ri ri k\'utin re k\'uwi\', ri rechajch\'aj e ri ri winaq ulew; man chi\' uk\'ux k\'uwi\' chi\' ri q\'atij k\'utin, jun ri ajk\'otaj rech ri q\'atij ri winaq, ri chik\'in e chi\' chi\' ri winaq chiri\' rechajch\'aj k\'uwi\' uk\'ux, ri Rechajch\'aj uk\'ux q\'atij e re k\'utin.</span>
<br><span>Re ati\'taj k\'u\'x tijob\'alaj, ri q\'atij rechajch\'aj ri rechajch\'aj chik\'in</span>
', '<p>Principio tu Equilibrio Orgánico (2×3).</p>
<p>Jo’oj, Balansar, Tukuch.</p>
<p>Le ritmilo’ob ku meyaj tu’ux ku sáamal balansar u xikinilil.</p>
<p>Le hexágono’ ku patik u k’áak’alil ka’analil k’áax yéetel célula.</p>
<p>Kíimbala’ ku chan u jump’éel estado nojoch túumben túukulil.</p>', '<p>Principle of Organic Balance: 2x3. (Polarity through Rhythm)</p>
<p>Equality, Balance, Organize.</p>
<p>The polarity of rhythm generates the organic principle, the law of the Hexagonal ordering of crystalline and cellular structures. The tendency of structures linked to the process of life is to reach relative equilibrium, an intermediate state of realization, from which to continue movement towards higher consciousness.</p>
<p>The principle of Potential Difference provides the resolution of situations through qualitative leaps between states of energy. Nothing that happens is casual, everything is subject to the power of the primordial law; every effect has its cause and at the same time is causal of other effects, the First Central Cause is the Creator.</p>
<p>Its action is to balance, the principle of integration of our introspection.</p>
', '<p>
    <strong>K\'u\'xaj:</strong><br>
    <span>Jun ruxe\'l ri k\'ojojil rik\'in: 2 × 3 — ri jastej ri ruk\'ux jaloj pa ri ruxaq.</span>
</p>
<p>
    <span>Tz\'ijol, winaqil, chiqajixik.</span><br>
    <span>Ri jastej ruk\'ux jaloj k\'ut k\'o wi ri k\'u\'x ri qachoch, ruk\'ux ri winaq, ch\'uqaʼ ri ruk\'ux ri qak’aslemal.</span><br>
    <span>Ri wachoch ri ruk\'ux ri qak’aslemal k\'o wi ri taq hexágono pa ri ajch\'ajil ri kristal ch\'uqaʼ ri taq ch\'och\'.</span><br>
    <span>Ri ruk\'oxik ri nimaläj b\'anikil kachoch ri k’aslemal k\'ut katz\'ib\'aj pa jun k’ojlem chi re k\'u\'x,
           toq k\'o wi kitijoj k\'u\'x chi ke ri ajawanel.</span>
</p>
<p>
    <span>Ri rucholajil “Diferencial” k\'u\'x chi kamul qakamisal taq b\'anikil,
           katob’ana\'; xa xe jun k\'ayib\'äl k\'ut chikamäj ri k’uxaj taq ruk’isib’al.</span><br>
    <span>Ma k\'o ta qa k\'ut xk’ulmataj – ronojel k’o wi chi rukematz\'ib’ ri ruk’amal k’ojlem;
           ronojel samaj k’o wi jun k’uxaj, k’ax kachiʼ pa jun chi re. Ri Nab\'ey Ajk\'amab’äl
           ja ri Ajaw.</span>
</p>
<p>
    <span>Kare ri k’amal re Waqibʼ ja ri tik’arisaj ri qasik’ij,
          ri k\'u\'xajil ri k\'ojlapetik ri qach\'abwäch.</span>
</p>');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (7, 'Wuqub\'', 'El Equilibrio, El Movimiento, El Integrar, El Realizar', 'Principio de unificación mental. (Poder místico)<br><span></span>Armonización, Inspirar, Canalizo.<br><span></span>Los hombres somos unidades resonantes dentro de un todo Mental, el orden material es un fractal del ordenamiento mental del universo; nosotros no controlamos la mente, somos pensados por la mente, vivimos inmersos en ella.<br><span></span>El siete canaliza energía inspirando la armonización. Representa las fases lunares de 7 días, el segundo paso de la transformación interior; el intelecto activo, inquieto, la influencia lunar.', 'Uuk', 'Energia_7', '<span>Principio de unificación mental. (Poder místico)</span>
<br><span>Utzijilaj, Xk\'utinaj, Winaq\'ij.</span>
<br><span>Re winaq ri k\'utinaj rechajch\'aj ulew ri rech q\'ij, re k\'ajk\'otaj k\'uwi\' rech ri ulew k\'ojojilal, ri ri q\'utin k\'utin re ri rech q\'ij e re winaq; ri rechajch\'aj chi\' ri winaq chi\' re ri q\'ij, winaq rechajch\'aj re k\'ojojilal, ri chik\'in ruk\'ub\'al rechajch\'aj k\'uwi\' chik\'in ri winaq k\'ojojilal.</span>
<br><span>Re wajxaj ri utz\'ib\' utzij re utzijilaj ri k\'uwi\' xk\'utinaj. Utzijilaj jun tijob\'al e rechajch\'aj k\'uwi\' e ri utz\'ib\' ronojel e re winaq. Utzijilaj ri winaq wach ri winik\'ab\' re winaq ruk\'ub\'al ulew, rechajch\'aj wach uch\'ab\'al re k\'ojojilal re winaq.</span>
<br><span>Ri wakaxaj e jun rechajch\'aj wach uch\'ab\'al, ri rechajch\'aj winaq wach uch\'ab\'al, uk\'uxaj e utzijilaj k\'uwi\' ri k\'utinaj, ri winaq ajk\'otaj chiri\' ri k\'uwi\' rechajch\'aj ri utz\'ib\' e rechajch\'aj winaq.</span>
', '<p>Principio tu Unificación Mental.</p>
<p>Ats’aats’, Inpirar, Jo’osal.</p>
<p>Táan k’uxajilo’ob ichil junp’éel tuukul; le materialil jump’éel fractal tu mentalil kaab.</p>
<p>Le wákxak ku kanal u tsol, tu’ux ku inpirar ats’aats’.</p>
<p>U meyaj ku meyaj yéetel ja’ ts’íits’ u k’iinil Luna (7 k’iin).</p>', '<p>Principle of Mental Unification. (Mystical Power)</p>
<p>Harmonization, Inspire, Channel.</p>
<p>We are resonant units within a Mental whole; the material order is a fractal of the mental ordering of the universe. We do not control the mind; we are thought by the mind, living immersed in it.</p>
<p>The seven channels energy by inspiring harmonization. It represents the lunar phases of 7 days, the second step of inner transformation; the active, restless intellect, the lunar influence.</p>
', '<p>
 Ri\' xk\'utij wi\' riwajil <em>de unificación mental. (Poder místico)</em> <br>
 <span></span> <br>
 Armonización, Inspirar, Canalizo. <br>
 <span></span> <br>
 Wi\' winaq chik\' xukasikinik ri\' tinamit k\'i\' wi\' tinamit Mental, ri\' k\'u\'xaj k\'i\' tinamit xub\'anik k\'o\' wi\' tinamit ruk\'ub\'al k\'i\' tinamit ulew; k\'u\'xaj xub\'anik k\'o\' wi\' k\'o\' tinamit, winaq ri\' tinamit k\'u\'xaj riwajil tinamit, winaq ruch\'aj k\'o\' k\'u\'xaj xub\'anik. <br>
 <span></span> <br>
 Ri\' laj maya\' k\'o\' xch\'ijtij chi\' juyub\'aj canalizo\' juyub\'aj inspirando armonización. K\'i\' chik\' winaq ulew k\'i\' tinamit, ruk\'ub\'al ruk\'ub\'al k\'o\' tinamit ch\'uti\'al, ri\' chi\' ruk\'ub\'al k\'o\' transformación interior; tinamit chik\' k\'ut ruch\'aj, k\'utin k\'i\' k\'u\'xaj, tinamit influencia lunar.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (8, 'Wajxaqib\'', 'La Espiritualidad, El Arte, La Alegría, La Energía Masculina', 'Principio de Resonancia armónica. (Octavas resonantes)<br><span></span>Integridad, Modelar, Armonizar.<br><span></span>Así como en música, las escalas se suceden en octavas, las energías vibratorias contactan y resuenan con sus respectivas equisonantes en los niveles superiores e inferiores de manifestación, como también con los armónicos secundarios derivados de la vibración.<br><span></span>Las octavas son el vehículo de información del todo, como ley de la armonía; el tono ocho otorga la habilidad de dar forma, de modelar, de describir aspectos del nivel inmediatamente superior de vibración.<br><span></span>Ocho es la esencia interior, el ser como recipiente de la esencia cósmica, el 2 veces NAHUI (4), conjuga las 4 direcciones (+) y los 4 rincones (X) del mundo.', 'Waxac', 'Energia_8', '<span>Principio de Resonancia armónica. (Octavas resonantes)</span>
<br><span>Utq\'ijilaj, Ri utq\'ijilaj, Tijob\'alaj.</span>
<br><span>Chi ri musikaj, ri chik\'inaj rechajch\'aj chi\' uk\'ux re wi\' k\'ojojilal, ri ri winaq k\'utin chi\' ri ajk\'ojolaj winaq k\'ojojilal uk\'ux e q\'atij re winaq ri ajk\'ojolaj, chiri\' rechajch\'aj e ri winaq k\'utin k\'ojojilal re q\'atij re ajk\'ojolaj re q\'atij e ri ulew q\'utin ri k\'ojojilal xk\'utin e re winaq k\'ojojilal uk\'ux re ri k\'ojojilal winaq.</span>
<br><span>Re uk\'ux rechajch\'aj re ri winaq k\'utin re ri ati\'taj, chiri\' ri winaq e utq\'ijilaj; ri k\'ojojilal oxib\' ri q\'atij, ri chik\'in ronojel ri winaq, ri utq\'ijilaj wach uch\'ab\'al re k\'ojojilal chik\'in ri ajk\'ojolaj uk\'ux ri winaq k\'ojojilal.</span>
<br><span>Uch\'ab\'al k\'ojojilal uk\'ux ri chik\'in, re ajk\'ojolaj chi\' uk\'ux re chik\'in ajk\'ojolaj, rechajch\'aj e rechajch\'aj k\'ojojilal e ri winaq k\'ojojilal, ri 2 wa NAHUI (4), chuwach ri 4 ruk\'ub\'al (+) e rechajch\'aj ruk\'ub\'al (X) ri winaq.</span>
', '<p>Principio tu Resonancia Armónica (Octava).</p>
<p>Integro, Ts’áa, Ats’aats’.</p>
<p>Bey mixbail, le escalalo’ob ku súut u chi’bal ichil octavo’ob.</p>
<p>Le oktavo’ ku k’a’am ba’axilil infromasióon; le tono 8 ku ts’áa u forma.</p>
<p>Ocho ku yaan yóok’ol le 4 k’iin + 4 tu’ux le lu’um.</p>', '<p>Principle of Harmonic Resonance. (Resonant Octaves)</p>
<p>Integrity, Shape, Harmonize.</p>
<p>Just as in music, scales occur in octaves, vibrational energies contact and resonate with their respective counterparts at higher and lower levels of manifestation, as well as with the secondary harmonics derived from vibration.</p>
<p>Octaves are the vehicle of information of the whole, as the law of harmony; the tone eight grants the ability to shape, to mold, to describe aspects of the immediately higher level of vibration.</p>
<p>Eight is the inner essence, the being as a receptacle of cosmic essence, the 2 times NAHUI (4), combines the 4 directions (+) and the 4 corners (X) of the world.</p>
', '<p>
 Ri\' xk\'utij wi\' riwajil <em>de Resonancia armónica. (Octavas resonantes)</em> <br>
 <span></span> <br>
 Integridad, Modelar, Armonizar. <br>
 <span></span> <br>
 Ja\' k\'o\' tinamit xk\'utij, tinamit k\'o\' saqirinik ri\' escalas ri\' xk\'utij chuwach k\'o\' octavas, tinamit chukir xk\'utij tinamit wi\'chik\'utinik k\'i\' k\'u\'xaj k\'utinik xub\'anik tinamit chuwach ruk\'ub\'al k\'i\' tinamit xukasikinik k\'o\' chik\' ri\' tinamit. <br>
 <span></span> <br>
 Ri\' octavas xuk\'utik tinamit k\'o\' tinamit k\'i\' ruk\'ub\'al xk\'utij, k\'i\' k\'u\'xaj tinamit k\'o\' k\'u\'xaj k\'i\' tinamit k\'i\' tinamit k\'utinik ruk\'ub\'al xub\'anik tinamit. Ri\' winak ocho k\'o\' tinamit k\'i\' tinamit ruk\'ub\'al, tinamit wi\' chik\' ri\' chak\'uj ruk\'ub\'al tinamit, tinamit k\'o\' tinamit k\'i\' tinamit xub\'anik k\'o\' tinamit ruk\'ub\'al k\'o\' ruk\'ub\'al tinamit.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (9, 'B\'elejeb\'', 'La Realización, El Poder, Acción, La Energía Femenina', 'Principio de la Periodicidad cíclica.<br><span></span>Intención, Realizar, Pulso.<br><span></span>Todo cuanto se mueve lo hace de acuerdo a la Ley Cósmica; la periodicidad cíclica, no la repetición de los sucesos, es la cualidad por la que un evento se asocia a otros anteriores y posteriores en el tiempo como fenómenos resonantes (ciclos entre ciclos).<br><span></span>Representa lo femenino del principio generatriz (Yin), el polo creativo en el cual se manifiesta la generación o producción de formas, energías y conceptos nuevos dinamizadores del proceso evolutivo de la vida, el objetivo; la intención de poner la acción en movimiento', 'Bolon', 'Energia_9', '<span>Principio de la Periodicidad cíclica.</span>
<br><span>Utzij, Ronoqilal, Xk\'uch\'ulaj.</span>
<br><span>Re k\'aslemal chik\'in, ati\'taj chiri\' re k\'ajk\'otaj ulew k\'ojojilal; ri q\'atij tzij ri k\'utin, k\'ojojilal ati\'taj xk\'utin e re k\'ajk\'otaj ulew k\'ojojilal, re ulew q\'utin xk\'utin k\'ojojilal chik\'in ajk\'ojol e ri chik\'in ajk\'ojol e ri re winaq k\'utin chiri\' re k\'ojojilal (k\'utin chiri\' re k\'ojojilal).</span>
<br><span>Ati\'taj ri k\'ojojilal ri ri k\'ajk\'otaj ajk\'ojolaj (Yin), re poy k\'utin chiri\' re winaq k\'ojojilal ri re k\'ajk\'otaj ri ulew e uk\'ux k\'uwi\' rechajch\'aj ati\'taj chik\'in ri chik\'in e uk\'ux k\'uwi\' k\'utin e ri k\'aslemal, ri ati\'taj; ri utzij k\'uwi\' chiri\' ri k\'utin ronoqilal e re winaq.</span>
', '<p>Principio tu Ciclo.</p>
<p>Ich’am, Tso’ook, Pulso.</p>
<p>Ba’ax ku meyaj ku meyaj según Ley Kósmica; ma’ repetisión, sí periodicidad.</p>
<p>Representa le ts’ib femenina (Yin), túumben óoltajilo’ob, energías, conceptos.</p>', '<p>Principle of Cyclical Periodicity.</p>
<p>Intention, Accomplish, Pulse.</p>
<p>Everything that moves does so according to Cosmic Law; cyclical periodicity, not the repetition of events, is the quality by which an event is associated with others both preceding and succeeding it in time as resonant phenomena (cycles within cycles).</p>
<p>It represents the feminine aspect of the generative principle (Yin), the creative pole in which the generation or production of new forms, energies, and concepts that drive the evolutionary process of life, the objective, manifest; the intention to set action in motion.</p>
', '<p>
    Ri\' xk\'utij wi\' riwajil <em>de la Periodicidad cíclica.</em> <br>
    <span></span> <br>
    Intención, Realizar, Pulso. <br>
    <span></span> <br>
    Ri\' juyub\'aj k\'o\' k\'u\'xaj ruch\'aj chuwach k\'o\' tinamit k\'i\' Tinamital ri\' chukir juyub\'aj; ri\' juyub\'aj ruk\'ub\'al k\'i\' k\'u\'xaj juyub\'aj, xk\'utij k\'i\' k\'u\'xaj ruk\'ub\'al tinamit k\'i\' tinamit k\'ut xk\'utij k\'o\' ri\' tinamit k\'o\' tinamit k\'ut ruch\'aj k\'i\' k\'utinik k\'o\' tinamit k\'utinik (juyub\'aj k\'o\' juyub\'aj ri\' juyub\'aj). <br>
    <span></span> <br>
    K\'utinik wi\' k\'i\' ruk\'ub\'al ruk\'ub\'al ri\' xk\'utij ruch\'aj (Yin), ri\' xk\'utij xub\'anik k\'o\' tinamit chukir k\'i\' chukir k\'o\' tinamit chik\' chik\' k\'i\' tinamit xk\'utij chuch\'utinamit, tinamit xub\'anik k\'o\' tinamit k\'i\' tinamit tinamit k\'i\' ch\'uti\'al ruch\'aj tinamit, tinamit k\'i\' chik\'ut chik\' wi\' k\'i\' ruch\'aj ri\' k\'ut k\'i\' tinamit ruch\'aj.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (10, 'Lajuj', 'La Ley, La Autoridad, La Rectitud, La Impecabilidad', 'Principio de la Manifestación.<br><span></span>Manifestar, Producir, Perfecciono.<br><span></span>El movimiento como energía se manifiesta en cada nivel u octava de vibración (dimensión); todo lo que se manifiesta, es decir, que cobra presencia (objetiva o subjetiva) se puede medir y viceversa.<br><span></span>La manifestación de la energía en todos los planos, implica vencer o enfrentar los obstáculos inherentes al plano dimensional y al tipo de presencia a manifestarse. Las manos juntas, la dualidad de las manos (5+5=10), equilibrándose mutuamente, como flecha al objetivo.', 'Lajun', 'Energia_10', '<span>Principio de la Manifestación.</span>
<br><span>Ati\'taj, Xk\'utin, K\'ajch\'aj.</span>
<br><span>Re ch\'ajaq ri k\'aslemal chi\' re winaq re ri winaq rech k\'uwi\' e ulew k\'utin (uk\'ux); jun rech ri k\'ajch\'aj, ati\'taj re winaq rech k\'utin k\'uwi\' (winaq uk\'ux ri winaq winaq k\'ojojilal) chiri\' rech ri ajk\'ojolaj, ri\' winaq k\'ojojilal e ri q\'utin chiri\' rech k\'utin.</span>
<br><span>Ri ati\'taj e re winaq ri re ajk\'ojolaj uk\'ux ulew, chiri\' rech uk\'ux k\'ojojilal k\'utin e q\'utin winaq chiri\' re ajk\'ojolaj e chik\'in ati\'taj winaq rech k\'utin k\'uwi\'. Re ruq\'ij ri\'ti\', re q\'utin e re winaq ri winaq (5+5=10), rechajch\'aj jun e rechajch\'aj, chiri\' ri k\'utin k\'uwi\'.</span>
', '<p>Principio tu Manifestación.</p>
<p>Manifestar, K’emk’ent, Perfectuar.</p>
<p>Le meyajil energía ku ja’atsik tu cada octava de vibración.</p>
<p>Tsooj u yóok’olil u’obstáculo’ob, jump’éel balansi 5+5 k’ab.</p>', '<p>Principle of Manifestation.</p>
<p>Manifest, Produce, Perfect.</p>
<p>Movement as energy manifests at each level or octave of vibration (dimension); everything that manifests, that is, that becomes present (objectively or subjectively) can be measured, and vice versa.</p>
<p>The manifestation of energy on all planes involves overcoming or facing the obstacles inherent to the dimensional plane and the type of presence to be manifested. Hands together, the duality of hands (5+5=10), balancing each other, like an arrow to the target.</p>
', '<p>
 <em>Xoqinajil kaj</em> <br>
 <span></span> <br>
 Xoqinajil, Ri\'ol, Ch\'otij. <br>
 <span></span> <br>
 Ri\' xk\'utij k\'o\' energia ri\' xuquje\' ri\' ulew k\'ab\'äl k\'i\' ri\' xk\'utij ulew tinamit (dimensión); ri\' ulew k\'o\' xk\'utij tinamit, k\'o\' xk\'utij ri\' ulew tinamit (objetiva k\'i\' subjetiva) ri\' xk\'utij tinamit tinamit k\'o\' xuk\'utik. <br>
 <span></span> <br>
 Ri\' xk\'utij k\'o\' ri\' ulew tinamit, k\'o\' ri\'wach k\'o\' xuk\'utik ri\' tinamit k\'o\' xuwe\'ek tinamit ri\' ulew k\'o\' ri\'wach tinamit k\'o\' xuwe\'ek tinamit tinamit. Ri\' chik tinamit ch\'uti\', ri\' chik tinamit ch\'uti\' (5+5=10), xuk\'utik tinamit, k\'i\' chik tinamit k\'o\' ta chik tinamit k\'i\' xk\'utij tinamit.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (11, 'Julajuj', 'Compartir, Separar, Las Posibilidades, Dejarse-abandonarse', 'Principio de las Estructuras disonantes.<br><span></span>Liberación, Divulgar, Disolver.<br><span></span>Todas las estructuras, cualquiera sea su naturaleza, tienden a ingresar a nuevas realidades; el movimiento perpetuo implica mutación y cambio constante, en la vida vamos haciendo conscientes estas nuevas realidades.<br><span></span>Las estructuras que se "desordenan" como un aparente caos para el mundo material, en realidad están ingresando a otro orden superior no comprensible desde la tridimensional. La grieta que nos escinde del todo es la no evolución, nuestra tendencia a quedarnos resguardados donde nos sentimos cómodos y seguros es un espejismo; un orden superior que hoy asimilamos como caos esta a la espera de nuestro ingreso, es la quinta dimensión que trasciende a las anteriores', 'Buluk', 'Energia_11', '<span>Principio de las Estructuras disonantes.</span>
<br><span>Q\'atij, Ri b\'antaj, Ri q\'ut\'olaj.</span>
<br><span>Rech ajk\'ojolaj, rech ri ulew, xk\'utin e ulew xk\'utin ri q\'ak\'altun, ati\'taj chiri\' ti\'ik\' ri q\'ak\'altun xk\'utin chiri\' rech ulew ri uk\'ux winaq; rech k\'ajk\'otaj chi re q\'ojolaj e q\'ajolaj q\'utin ati\'taj ri k\'ajolaj tijob\'al ri\' re winaq ri ajk\'ojolaj e q\'ajolaj q\'utin.</span>
<br><span>Rech ajk\'ojolaj xk\'utin rech ri "riwach\'owin" chiri\' xk\'utin, ajk\'ojolaj chiri\' ri uk\'ux e ulew winaq, jun b\'e ri k\'ojojilal wachaj, rech ri q\'utin q\'utin ajk\'ojolaj e ri q\'utin ulew e ri ulew winaq, rech ri ri ajk\'ojolaj q\'utin ri winaq, ri q\'utin, rech ri aq\'ab\'al.</span>
', '<p>Principio tu Estructuras Disonantes.</p>
<p>Ts’íibil, Dispersar, Tz’uts’.</p>
<p>To’on estructuras ku k’exik ichil nuevos realidades; meyaj perpetuo ku táan jump’éel mutación.</p>
<p>Le aparente kaos ku sáamal tu orden túumben (5ª dimensión) más nahil.</p>', '<p>Principle of Dissonant Structures.</p>
<p>Liberation, Dissemination, Dissolution.</p>
<p>All structures, regardless of their nature, tend to enter new realities; perpetual movement implies mutation and constant change, in life we become aware of these new realities.</p>
<p>The structures that "disorder" as an apparent chaos to the material world are actually entering another higher order not understandable from the three-dimensional perspective. The crack that splits us from the whole is non-evolution, our tendency to stay sheltered where we feel comfortable and safe is an illusion; a higher order that we currently assimilate as chaos awaits our entry, it is the fifth dimension that transcends the previous ones.</p>
', '<p>
 <em>Xoqinajil xk\'utij</em> <br>
 <span></span> <br>
 Kajolajuj, Laj, Xukun. <br>
 <span></span> <br>
 Ruk\' ri\' xk\'utij, ora rik\'axik rik\'utij, k\'ux ri\' xuquje\' xuquje\' xk\'utij k\'o\' ulew ch\'uti\'; ri\' k\'o\' xb\'antäqäl rik\'aj k\'i\' ruk\' ch\'utinamit xk\'utij, k\'o\' xk\'utij xk\'utij k\'o\' ruk\' ulew xk\'utij xk\'utij. Ri\' xuquje\' k\'o\' k\'ux k\'o\' xuquje\' k\'o\' ruk\' ch\'uti\' xk\'utij xk\'utij k\'o\' ch\'utinamit, ri\' chik tinamit ri\' k\'uq k\'o\' xuwe\'ek tinamit chik ch\'utinamit ulew qak\'ixoj. Ri\' k\'o\' xk\'utij xuwe\'ek xuquje\' xuwe\'ek k\'ux k\'o\' noj k\'o\' chik xk\'utij k\'i\' qak\'ixoj k\'i\' ruk\' chik tinamit xk\'utij ri\' k\'uq xuwe\'ek xuquje\' k\'ux k\'o\' xk\'utij ch\'utinamit k\'o\' ulew k\'o\' xk\'utij k\'o\' k\'uq xuquje\'.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (12, 'Kab\'lajuj', 'La Familia, La Comunidad, Los Grupos, La Seguridad', 'Principio de la Estabilidad compleja: 2x6.<br><span></span>Cooperación, Universalizar, Dedicación.<br><span></span>Es la polarización del equilibrio orgánico, mediante el cual cada especie gana su propio nivel de frecuencia armónica, es decir, su estatuto como especie: código, nicho, hábitat, etc. Genera las fuerzas conservacionistas de los organismos vivos, incluida la tierra, como cooperación simbiotica.', 'Kaalajun', 'Energia_12', '<span>Principio de la Estabilidad compleja: 2x6.</span>
<br><span>Xk\'utin, K\'utijolaj, Winaqikaj.</span>
<br><span>Ati\'taj k\'ak\'alikaj e k\'ak\'alaj k\'utin re q\'ak\'altun, xk\'utin re ajk\'ojol rech ri xk\'utin winaq chiri\' rech k\'uwi\' winaq k\'ojojilal, o sea, k\'u\'x ri rech ri q\'ak\'altun: ti\', k\'o\', tiwan, chikinik, k\'u\'x e k\'ojojilal. Ati\'taj k\'u\'x rech k\'ojojilal chiri\' re q\'ak\'altun winaq, k\'utin k\'u\'x rech ulew, k\'u\'x ri chik\'inaj k\'utin chiri\' re winaq re k\'ak\'ul, ati\'taj k\'u\'x ri ri winaq ri\' ulew.</span>
', '<p>Principio tu Estabilidad Compleja (2×6).</p>
<p>Mejen, Universal, Mets’.</p>
<p>Le polaridad tu hexágono ku ts’áa a cada especie u propia frecuencia.</p>
<p>Ku jóok’ u fuerzas conservadoras tu kuxtal yéetel le Lu’um.</p>', '<p>Principle of Complex Stability: 2x6.</p>
<p>Cooperation, Universalize, Dedication.</p>
<p>It is the polarization of organic balance, through which each species gains its own level of harmonic frequency, that is, its status as a species: code, niche, habitat, etc. It generates the conservative forces of living organisms, including the earth, as symbiotic cooperation.</p>
', '<p>
 <em>Xoqinajil xk\'utij k\'ame\': 2x6</em> <br>
 <span></span> <br>
 Tuqoj, Chiq\', Uq\'ijil. <br>
 <span></span> <br>
 Ri\' chi\' b\'antäqäl xk\'utij tuq\'asikik, ora rik\'utij xuwe\'ek k\'uq b\'antäqäl tuq\'asikik, rik\'uch kajawirikil ri\' chi\' b\'antäqäl xk\'utij, chi\' ronojel, k\'iwächij, chiri\', rume\' chik\'inamit ri\' chi\' b\'antäqäl xk\'utij kajawirik. Xk\'utij ri\' chi\' uq\'ijil b\'antäqäl chi\' rumal ri\' chi\' winaq rik\'utij, k\'o\' k\'ajolajujel, ulew tierra, xk\'utij tuq\'asikik xk\'utij.
</p>
');
INSERT INTO tiempomaya.energia (id, nombre, significado, htmlCodigo, nombreYucateco, categoria, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (13, 'Oxlajuj\'', 'La Magia, EL Poder del Camino, La Teurgia, El Trasmutar', 'Principio del movimiento universal o principio de vibración.<br><span></span>Presencia, Trascender, Perdurar.<br><span></span>Todo cuanto existe esta en perpetuo movimiento, desde lo mas sutil con las vibraciones, hasta lo mas denso y pesado como expresión de las bajas frecuencias, a tal punto que estos extremos parecen en reposo. <br><span></span>El movimiento es la energía que fluye desde la fuente y regresa a ella. Este principio otorga trascendencia a todo lo que funciona con y obedece a la ley del uno, trascendencia es la cualidad de perdurar mas allá del tiempo y del espacio. La unión total de todos los números anteriores, el ultimo numero representa el conocimiento interno, la introspección, centralidad y transparencia, Sabiduría del Universo, La Madre Tierra, respeto a lo que existe, florece y da frutos.', 'Oxlajun', 'Energia_13', '<span>Principio del movimiento universal o principio de vibración.</span>
<br><span>Tijob\'al, Rok\'aj, Ratz\'aj.</span>
<br><span>Rech k\'aslemal wach ulew xk\'ut re k\'oj.</span>
<br><span>Jun chwej e xk\'ut chwej e k\'ajol, chi ri k\'aslemal k\'olom, xk\'ut chi ri k\'aslemal xk\'olom e k\'utin e uk\'ux ri wi, re winaq ri\' uk\'u\'x.</span>
<br><span>Tijob\'al ri jolom re winaq ri k\'aslemal chiri\' re uk\'ux e k\'utin e winaq xk\'utin, tijob\'al ri\' xk\'utin k\'utin wi\', tijob\'al k\'u\'x ri k\'utin xk\'utin winaq, ratz\'aj k\'i\' k\'uwi\' uk\'ux k\'uwi\' re winaq xk\'utin chi k\'ajol e winaq xk\'utin e ri k\'ojojilal, ratz\'aj k\'i\' tijob\'al winaq, ratz\'aj k\'i\' k\'olom xk\'utin winaq.</span>
', '<p>Principio tu Vibración Universal.</p>
<p>Presensia, Transender, Permanesér.</p>
<p>Ba’ax tu yaan táan ts’u’uts’ tu meyaj; le u’uchbenhasta le más ka’ach ku páajtal.</p>
<p>U movimiento ku súut ti’ si’ipil ka’ach yéetel túmben kéej.</p>
<p>Trese ku juntóol ts’íib; sabiduría yóok’ol kaab, u yaakunaj le máako’ yéetel le Lu’um.</p>', '<p>Beginning of the universal movement or principle of vibration.</p>
<p>Presence, Transcendence, Permanence.</p>
<p>Everything that exists is in perpetual motion, from the most subtle vibrations to the densest and heaviest expressions of low frequencies, to the point that these extremes appear at rest.</p>
<p>Movement is the energy that flows from the source and returns to it. This principle grants transcendence to everything that operates with and obeys the law of one; transcendence is the quality of enduring beyond time and space. The total union of all preceding numbers, the last number represents internal knowledge, introspection, centrality, and transparency, Wisdom of the Universe, Mother Earth, respect for what exists, flourishes, and bears fruit.</p>
', '<p>
 <em>Ch\'uti\'x ulew ri wi\' chikop k\'ut xk\'utij</em><br>
 <span></span><br>
 <em>Po\'j,</em> <em>Ulew chiwe,</em> <em>Uch\'aj,</em><br>
 Ri chikop xk\'utij ora rik\'utij k\'ut wi\' ronojel, k\'ajolajuj k\'ut xuwe\'ek chikop rik\'utij xuwe\'ek chikop k\'uq, ora rik\'utij xk\'utij k\'ut k\'ajolajuj chi\' rik\'utij xk\'utij xk\'utij xuwe\'ek k\'ut chikop k\'uq, u q\'ij ri k\'uq chikop winaq rik\'utij. Ri ulew chikop k\'ut xuwe\'ek chikop xk\'utij k\'ut winaq xuwe\'ek winaq rik\'utij.
</p>
');
